<script setup lang="ts">
import { ref, reactive } from 'vue'
import type { FormInstance, FormRules } from 'element-plus'
import { useRoute, useRouter } from 'vue-router'
import { ArrowRight, Tickets, Reading, Connection } from '@element-plus/icons-vue'
import { useAuth } from '../stores/auth'
import { demo } from '../api'
import { errorText } from '../utils'
const auth = useAuth(), route = useRoute(), router = useRouter()
const form = reactive({ username: '', password: '' })
const formRef = ref<FormInstance>()
const loading = ref(false), error = ref('')
const rules: FormRules = { username: [{ required: true, message: '请输入用户名', trigger: 'blur' }], password: [{ required: true, message: '请输入密码', trigger: 'blur' }] }
async function login() {
  if (!await formRef.value?.validate().catch(() => false)) return
  loading.value = true; error.value = ''
  try { await auth.login(form.username, form.password); const redirect = route.query.redirect; await router.replace(typeof redirect === 'string' && redirect.startsWith('/') && !redirect.startsWith('//') ? redirect : '/workbench') } catch (e) { error.value = errorText(e) } finally { loading.value = false }
}
function fill(username: string) { form.username = username; form.password = 'Demo123!'; error.value = '' }
</script>
